def build(p):
    od = p["outer_d"] / 2
    id_ = p["inner_d"] / 2
    h = p["length"]

    wp = cq.Workplane("XZ").moveTo(id_, 0).lineTo(od, 0)

    if p["groove"]:
        gp = p["groove_pos"]
        gd = p["groove_depth"]
        gw = p["groove_w"]
